mapper.select:
/* isry.couns.constt.sndng.mapper.SndngMapper.selectChrctrSndngList - 개발지원팀 이태호 */
SELECT a.BBSCTT_ESNTAL_NO AS BBSCTT_ESNTAL_NO ,a.BBSCTT_TYPE_SE_CD AS BBSCTT_TYPE_SE_CD ,a.BBSCTT_TTL_NM AS BBSCTT_TTL_NM ,nvl(C##RG.DEC_B64(a.WRTR_NM_ENCPT), '-') AS WRTR_NM_ENCPT ,nvl(C##RG.DEC_B64(a.EML_ADDR_ENCPT), '-') AS EML_ADDR_ENCPT ,C##RG.DEC_B64(a.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT ,TO_CHAR(a.FRST_REG_DT,'YYYY-MM-DD') AS FRST_REG_DT ,EXTRACT(DAY FROM SYSTIMESTAMP - TO_TIMESTAMP(a.FRST_REG_DT,'YYYYMMDDHH24MI')) AS DT ,(SELECT y.MBL_TELNO_ENCPT FROM SAA200 x ,SCA200 y WHERE 1=1 AND x.YNGBGS_PRTCR_NO = y.YNGBGS_PRTCR_NO AND x.USER_ID = a.FRST_RGTR_ID AND ROWNUM =1) AS MBL_TELNO_ENCPT2 FROM AYE100 a /* 사이버상담게시글 */ WHERE 1=1 AND a.BBSCTT_TYPE_SE_CD = '03' AND a.CHRCTR_YN = 'N' AND a.END_YN = 'N' AND a.DEL_YN = 'N' AND EXTRACT(DAY FROM SYSTIMESTAMP - TO_TIMESTAMP(a.FRST_REG_DT,'YYYYMMDDHH24MI')) >= 30
AND a.FRST_REG_DT BETWEEN #{STARTDT} AND #{ENDDT}
AND C##RG.DEC_B64(a.WRTR_NM_ENCPT) LIKE '%' || #{WRTR_NM_ENCPT} || '%'
AND a.BBSCTT_TTL_NM LIKE '%' || #{BBSCTT_TTL_NM} || '%'
ORDER BY FRST_REG_DT

mapper.update:

 /* isry.couns.constt.sndng.mapper.SndngMapper.updateAYE100 - 개발지원팀 이태호  */
 UPDATE AYE100 /* 사이버상담게시글 */
     SET CHRCTR_YN               = 'Y'             
       , LAST_MDFR_ID            = #{userId}
       , LAST_MDFCN_DT           = SYSDATE
WHERE BBSCTT_ESNTAL_NO  = #{BBSCTT_ESNTAL_NO}
  and BBSCTT_TYPE_SE_CD = #{BBSCTT_TYPE_SE_CD}
